// vending_fsm.sv - balance FSM of the vending machine (Mealy): price 4, bills 1 / 3 / 5.
// Generated by scripts/emit_sv.py from scripts/fsms.py - do not edit by hand.
// Flip-flops: D, logic: minimal POS (exact two-level minimisation with don't-cares),
// next-state 16 two-input gates, outputs 30 two-input gates.
// State encoding:
//   b0     = 00
//   b1     = 01
//   b2     = 10
//   b3     = 11
// bill: 00 refund request, 01 = 1, 10 = 3, 11 = 5. item: 00 none, 01 one, 1X two.
// change: amount to return (0..3). en = 0 freezes the state and suppresses every output.

module vending_fsm (
  input  logic       clk,
  input  logic       rst,       // synchronous, balance 0
  input  logic       en,
  input  logic [1:0] bill,
  output logic [1:0] item,
  output logic [1:0] change,
  output logic [1:0] balance
);
  logic [1:0] bal;
  logic d1, d0, ch1, ch0, rf1, rf0;
  assign d1     = (~bal[1] | ~bal[0]) & (bill[1] | bill[0]) & (bal[1] | bal[0] | ~bill[0]) & (~bal[0] | ~bill[1]) & (~bal[1] | ~bill[1]);  // 10 gates
  assign d0     = (bill[1] | bill[0]) & (~bill[1] | ~bill[0]) & ~bal[0] & (~bal[1] | ~bill[1]);  // 6 gates
  assign ch1    = bal[1] & bal[0] & bill[1] & bill[0];  // 3 gates
  assign ch0    = (bal[1] | bal[0] | bill[0]) & (bal[1] | bill[1]) & (bal[0] | bill[1]) & (bill[1] | bill[0]);  // 8 gates
  assign rf1    = (bal[1] | bal[0]) & (bal[1] | bill[0]) & (bill[1] | ~bill[0]) & (bal[0] | ~bill[1] | bill[0]) & (~bal[1] | ~bal[0] | ~bill[0]);  // 11 gates
  assign rf0    = (bal[0] | bill[1]) & (~bal[0] | ~bill[1]) & (bal[1] | bal[0] | bill[0]) & (bill[1] | ~bill[0]);  // 8 gates

  always_ff @(posedge clk)
    if (rst)     bal <= 2'b00;
    else if (en) bal <= {d1, d0};

  assign item    = {ch1, ch0} & {2{en}};
  assign change  = {rf1, rf0} & {2{en}};
  assign balance = bal;
endmodule
